// 调度任务类型
export type TaskType =
  | "PERIODIC"
  | "DELAY"
  | "WAIT_RESULT";
// 任务执行状态
export type TaskExecutionStatus =
  | "ExecutionStatus_Unknown"
  | "ExecutionStatus_Success"
  | "ExecutionStatus_Failed";
// 调度任务控制类型
export type TaskControlType =
  | "ControlType_Start"
  | "ControlType_Stop"
  | "ControlType_Restart";
// 任务选项
export type TaskOption = {
  //
  // Behaviors: OPTIONAL
  retryCount?: number;
  //
  // Behaviors: OPTIONAL
  timeout?: wellKnownDuration;
  //
  // Behaviors: OPTIONAL
  deadline?: wellKnownTimestamp;
  //
  // Behaviors: OPTIONAL
  processIn?: wellKnownDuration;
  //
  // Behaviors: OPTIONAL
  processAt?: wellKnownTimestamp;
};

// 调度任务
export type Task = {
  //
  // Behaviors: OPTIONAL
  id?: number;
  //
  // Behaviors: OPTIONAL
  type?: TaskType;
  //
  // Behaviors: OPTIONAL
  typeName?: string;
  //
  // Behaviors: OPTIONAL
  taskPayload?: string;
  //
  // Behaviors: OPTIONAL
  cronSpec?: string;
  //
  // Behaviors: OPTIONAL
  taskOptions?: TaskOption;
  //
  // Behaviors: OPTIONAL
  name?: string;
  enable?: boolean;
  remark?: string;
  builtin?: boolean;
  lastExecution?: TaskExecution;
  createBy?: number;
  updateBy?: number;
  createTime?: wellKnownTimestamp;
  updateTime?: wellKnownTimestamp;
  deleteTime?: wellKnownTimestamp;
};

// 任务执行记录
export type TaskExecution = {
  id?: number;
  taskId?: number;
  typeName?: string;
  status?: TaskExecutionStatus;
  error?: string;
  startedAt?: wellKnownTimestamp;
  finishedAt?: wellKnownTimestamp;
  durationMs?: number;
  createTime?: wellKnownTimestamp;
};

// 查询调度任务列表 - 回应
export type ListTaskResponse = {
  items: Task[] | undefined;
  total: number | undefined;
};

// 查询调度任务详情 - 请求
export type GetTaskRequest = {
  id: number | undefined;
};

export type GetTaskByTypeNameRequest = {
  //
  // Behaviors: OPTIONAL
  typeName: string | undefined;
};

// 创建调度任务 - 请求
export type CreateTaskRequest = {
  data: Task | undefined;
};

// 更新调度任务 - 请求
export type UpdateTaskRequest = {
  data: Task | undefined;
  updateMask: wellKnownFieldMask | undefined;
  allowMissing?: boolean;
  id: number | undefined;
};

// 删除调度任务 - 请求
export type DeleteTaskRequest = {
  id: number | undefined;
};

// 重启调度任务 - 回应
export type RestartAllTaskResponse = {
  count: number | undefined;
};

// 任务处理器信息
export type TaskHandlerInfo = {
  typeName?: string;
  description?: string;
  payloadDescription?: string;
  payloadExample?: string;
};

// 查询任务执行记录 - 回应
export type ListTaskExecutionsResponse = {
  items: TaskExecution[] | undefined;
  total: number | undefined;
};

// 立即执行一次任务 - 请求
export type RunTaskRequest = {
  id: number | undefined;
};

// 查询已注册任务处理器清单 - 回应
export type ListTaskHandlersResponse = {
  items: TaskHandlerInfo[] | undefined;
};

